import{_ as n,c as a,o as p,ag as e}from"./chunks/framework.CQuhCYrb.js";const u=JSON.parse('{"title":"Maubot Plugins","description":"","frontmatter":{"title":"Maubot Plugins"},"headers":[],"relativePath":"general/maubot-plugins.md","filePath":"general/maubot-plugins.md","lastUpdated":null}'),l={name:"general/maubot-plugins.md"};function i(r,s,t,c,b,m){return p(),a("div",null,[...s[0]||(s[0]=[e(`<h1 id="maubot-plugins" tabindex="-1">Maubot Plugins <a class="header-anchor" href="#maubot-plugins" aria-label="Permalink to &quot;Maubot Plugins&quot;">​</a></h1><p><a href="/general/setting-up-maubot.html">up Maubot</a> for documentation ## Plugin Configurations ### React Bot <a href="https://github.com/maubot/reactbot" target="_blank" rel="noreferrer">https://github.com/maubot/reactbot</a></p><h4 id="proxyfront-end" tabindex="-1">ProxyFront End <a class="header-anchor" href="#proxyfront-end" aria-label="Permalink to &quot;ProxyFront End&quot;">​</a></h4><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>templates:</span></span>
<span class="line"><span>    nitter:</span></span>
<span class="line"><span>        type: m.room.message</span></span>
<span class="line"><span>        content:</span></span>
<span class="line"><span>            msgtype: m.text</span></span>
<span class="line"><span>            body: https://nitter.net/\${1}/status/\${2}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>default_flags:</span></span>
<span class="line"><span>- ignorecase</span></span>
<span class="line"><span>antispam:</span></span>
<span class="line"><span>    room:</span></span>
<span class="line"><span>        max: 1</span></span>
<span class="line"><span>        delay: 60</span></span>
<span class="line"><span>    user:</span></span>
<span class="line"><span>        max: 2</span></span>
<span class="line"><span>        delay: 60</span></span>
<span class="line"><span></span></span>
<span class="line"><span>rules:</span></span>
<span class="line"><span>    twitter:</span></span>
<span class="line"><span>        matches:</span></span>
<span class="line"><span>        - https://twitter.com/(.+?)/status/(\\d+)</span></span>
<span class="line"><span>        - https://x.com/(.+?)/status/(\\d+)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        template: nitter</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br></div></div><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>templates:</span></span>
<span class="line"><span>    invidious:</span></span>
<span class="line"><span>        type: m.room.message</span></span>
<span class="line"><span>        content:</span></span>
<span class="line"><span>            msgtype: m.text</span></span>
<span class="line"><span>            body: https://invidious.slipfox.xyz/watch?v=\${1}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>default_flags:</span></span>
<span class="line"><span>- ignorecase</span></span>
<span class="line"><span></span></span>
<span class="line"><span>rules:</span></span>
<span class="line"><span>    youtube:</span></span>
<span class="line"><span>        matches:</span></span>
<span class="line"><span>        - https://www.youtube.com/watch\\?v=(.+)</span></span>
<span class="line"><span>        template: invidious</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><h3 id="news-paywall-bypass" tabindex="-1">News Paywall Bypass <a class="header-anchor" href="#news-paywall-bypass" aria-label="Permalink to &quot;News Paywall Bypass&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>templates:</span></span>
<span class="line"><span>    newsarchiver:</span></span>
<span class="line"><span>        type: m.room.message</span></span>
<span class="line"><span>        content:</span></span>
<span class="line"><span>            msgtype: m.text</span></span>
<span class="line"><span>            body: Paywall Bypass of Your Link https://1ft.io/\${0}/\${1} -- OR-- https://12ft.io/\${0}/\${1} --OR-- https://web.archive.org/web/2023/\${0}/\${1}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>default_flags:</span></span>
<span class="line"><span>- ignorecase</span></span>
<span class="line"><span>antispam:</span></span>
<span class="line"><span>    room:</span></span>
<span class="line"><span>        max: 10</span></span>
<span class="line"><span>        delay: 5</span></span>
<span class="line"><span>    user:</span></span>
<span class="line"><span>        max: 20</span></span>
<span class="line"><span>        delay: 1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>rules:</span></span>
<span class="line"><span>    news:</span></span>
<span class="line"><span>        matches:</span></span>
<span class="line"><span>        - https://(www\\.)?nytimes.com/(.+)</span></span>
<span class="line"><span>        - https://(www\\.)?nyt.com/(.+)</span></span>
<span class="line"><span>        - https://(www\\.)?bbc.com/(.+)</span></span>
<span class="line"><span>        - https://(www\\.)?cnn.com/(.+)</span></span>
<span class="line"><span>        - https://(www\\.)?reuters.com/(.+)</span></span>
<span class="line"><span>        - https://(www\\.)?apnews.com/(.+)</span></span>
<span class="line"><span>        - https://(www\\.)?washingtonpost.com/(.+)</span></span>
<span class="line"><span>        - https://(www\\.)?usatoday.com/(.+)</span></span>
<span class="line"><span>        - https://(www\\.)?abcnews.go.com/(.+)</span></span>
<span class="line"><span>        - https://(www\\.)?nbcnews.com/(.+)</span></span>
<span class="line"><span>        - https://(www\\.)?aljazeera.com/(.+)</span></span>
<span class="line"><span>        - https://(www\\.)?theguardian.com/(.+)</span></span>
<span class="line"><span>        - https://(www\\.)?republicworld.com/(.+)</span></span>
<span class="line"><span>        - https://(www\\.)?independent.co.uk/(.+)</span></span>
<span class="line"><span>        - https://(www\\.)?thesun.co.uk/(.+)</span></span>
<span class="line"><span>        template: newsarchiver</span></span>
<span class="line"><span>## Add more rules as needed</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br></div></div><h3 id="rss-bot" tabindex="-1">RSS Bot <a class="header-anchor" href="#rss-bot" aria-label="Permalink to &quot;RSS Bot&quot;">​</a></h3><p><a href="https://github.com/maubot/rss" target="_blank" rel="noreferrer">https://github.com/maubot/rss</a> Basic commands:</p><ul><li><p><code>!rss subscribe &amp;lt;url&amp;gt;</code> - Subscribe the current room to a feed.</p></li><li><p><code>!rss unsubscribe &amp;lt;feed ID&amp;gt;</code> - Unsubscribe the current room from a feed.</p></li><li><p><code>!rss subscriptions</code> - List subscriptions (and feed IDs) in the current room.</p></li><li><p><code>!rss notice &amp;lt;feed ID&amp;gt; [- Set whether the bot should send new posts as m.notice</code> (if false, they’re sent as <code>m.text</code>).</p></li><li><p><code>!rss template &amp;lt;feed ID&amp;gt; [new template](true/false]</code>) - Change the post template for a feed in the current room. If the new template is omitted, the bot replies with the current template.</p></li></ul><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Feed update interval in minutes</span></span>
<span class="line"><span>update_interval: 60</span></span>
<span class="line"><span>## Maximum backoff in minutes when failing to fetch feeds (defaults to 5 days)</span></span>
<span class="line"><span>max_backoff: 7200</span></span>
<span class="line"><span>## The time to sleep between send requests when broadcasting a new feed entry.</span></span>
<span class="line"><span>## Set to 0 to disable sleep or -1 to run all requests asynchronously at once.</span></span>
<span class="line"><span>spam_sleep: 2</span></span>
<span class="line"><span>## The prefix for all commands</span></span>
<span class="line"><span>## It has to be prefixed with ! in matrix to be recognized</span></span>
<span class="line"><span>command_prefix: rss</span></span>
<span class="line"><span>## Default post notification template for new subscriptions</span></span>
<span class="line"><span>notification_template: &#39;New post in $feed_title: [$title](/link-title)&#39;</span></span>
<span class="line"><span>## Users who can bypass room permission checks</span></span>
<span class="line"><span>admins:</span></span>
<span class="line"><span>- &#39;@sac:irregularchat.com&#39;</span></span>
<span class="line"><span>- &#39;@sacmin:irregularchat.com&#39;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br></div></div>`,11)])])}const d=n(l,[["render",i]]);export{u as __pageData,d as default};
